import{c as s,Q as i,j as e,m as l}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuRandomTeleport 常见问题","description":"","frontmatter":{"title":"YuRandomTeleport 常见问题"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/faq.md","filePath":"plugins/items/yu-random-teleport/faq.md"}'),t={name:"plugins/items/yu-random-teleport/faq.md"};function n(p,a,o,h,d,r){return i(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="yurandomteleport-常见问题" tabindex="-1">YuRandomTeleport 常见问题 <a class="header-anchor" href="#yurandomteleport-常见问题" aria-label="Permalink to &quot;YuRandomTeleport 常见问题&quot;">​</a></h1><h2 id="执行-rtp-后提示找不到安全传送点" tabindex="-1">执行 <code>/rtp</code> 后提示找不到安全传送点 <a class="header-anchor" href="#执行-rtp-后提示找不到安全传送点" aria-label="Permalink to &quot;执行 \`/rtp\` 后提示找不到安全传送点&quot;">​</a></h2><p>常见原因：</p><ul><li><code>default.radius.min</code> 与 <code>default.radius.max</code> 范围内地形不可用。</li><li><code>height.min</code> 和 <code>height.max</code> 限制过窄。</li><li><code>allowed-materials</code> 白名单过于严格。</li><li><code>blocked-materials</code> 覆盖了目标世界大量地表方块。</li><li><code>safety.max-attempts</code> 太低。</li><li>下界高度范围没有覆盖可站立洞穴。</li></ul><p>排查建议：</p><ol><li>临时开启 <code>debug: true</code>。</li><li>查看控制台拒绝原因。</li><li>放宽 <code>allowed-materials</code> 或临时清空它。</li><li>提高 <code>safety.max-attempts</code> 到 <code>64</code> 测试。</li><li>针对目标世界单独设置 <code>worlds.&lt;世界名&gt;.height</code>。</li></ol><h2 id="为什么玩家移动后传送取消" tabindex="-1">为什么玩家移动后传送取消 <a class="header-anchor" href="#为什么玩家移动后传送取消" aria-label="Permalink to &quot;为什么玩家移动后传送取消&quot;">​</a></h2><p>这是等待打断机制。默认：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">teleport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  wait-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cancel-on-move</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>等待期间玩家移动位置、受伤、交互、聊天、执行命令或离线都会取消传送。视角转动不会取消。</p><p>如果希望立即传送：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">teleport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  wait-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><p>如果只想给特定玩家跳过等待，给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp.bypass.wait</span></span></code></pre></div><h2 id="开启经济后没有扣费" tabindex="-1">开启经济后没有扣费 <a class="header-anchor" href="#开启经济后没有扣费" aria-label="Permalink to &quot;开启经济后没有扣费&quot;">​</a></h2><p>请按顺序检查：</p><ol><li><code>economy.enabled</code> 是否为 <code>true</code>。</li><li><code>default.cost</code> 或世界配置中的 <code>cost</code> 是否大于 <code>0</code>。</li><li>是否安装 Vault。</li><li>是否安装经济插件并成功注册 Vault 经济服务。</li><li>命令执行者是否拥有 <code>yurtp.bypass.cost</code>。</li></ol><p>注意：扣费发生在成功传送后。找不到安全点或等待被取消时不会扣费。</p><h2 id="控制台能不能执行-rtp" tabindex="-1">控制台能不能执行 <code>/rtp</code> <a class="header-anchor" href="#控制台能不能执行-rtp" aria-label="Permalink to &quot;控制台能不能执行 \`/rtp\`&quot;">​</a></h2><p>控制台不能执行无参数 <code>/rtp</code> 或 <code>/yurtp</code>，因为控制台没有当前世界和玩家位置。</p><p>控制台可以执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yurtp &lt;玩家&gt;</span></span>
<span class="line"><span>yurtp &lt;玩家&gt; &lt;世界&gt;</span></span>
<span class="line"><span>yurtp reload</span></span></code></pre></div><h2 id="白名单和黑名单同时配置时谁优先" tabindex="-1">白名单和黑名单同时配置时谁优先 <a class="header-anchor" href="#白名单和黑名单同时配置时谁优先" aria-label="Permalink to &quot;白名单和黑名单同时配置时谁优先&quot;">​</a></h2><p>白名单优先。只要 <code>world-whitelist</code> 非空，插件就只允许白名单内世界执行随机传送。</p><p>示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">world-blacklist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lobby</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">world-whitelist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">resource</span></span></code></pre></div><p>此时只有 <code>resource</code> 允许 RTP，其他世界都会被拒绝，即使不在黑名单里。</p><h2 id="玩家有权限但仍无法代传送其他人" tabindex="-1">玩家有权限但仍无法代传送其他人 <a class="header-anchor" href="#玩家有权限但仍无法代传送其他人" aria-label="Permalink to &quot;玩家有权限但仍无法代传送其他人&quot;">​</a></h2><p>代传送需要满足两个条件：</p><ol><li>命令执行者拥有 <code>yurtp.teleport.others</code>。</li><li>目标玩家拥有 <code>yurtp.use</code>。</li></ol><p>如果目标玩家没有 <code>yurtp.use</code>，插件会返回权限不足。</p><h2 id="下界随机传送容易失败怎么办" tabindex="-1">下界随机传送容易失败怎么办 <a class="header-anchor" href="#下界随机传送容易失败怎么办" aria-label="Permalink to &quot;下界随机传送容易失败怎么办&quot;">​</a></h2><p>下界没有可靠的最高地表概念，插件会在高度范围内随机扫描候选 Y。建议给下界单独配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">worlds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  world_nether</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">118</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    safety</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      max-attempts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      allowed-materials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NETHERRACK&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SOUL_SAND&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SOUL_SOIL&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NETHER_BRICKS&quot;</span></span></code></pre></div><p>如果仍然失败，先关闭材质白名单测试，确认是高度问题还是方块限制问题。</p><h2 id="为什么自定义-title-命令没有效果" tabindex="-1">为什么自定义 title 命令没有效果 <a class="header-anchor" href="#为什么自定义-title-命令没有效果" aria-label="Permalink to &quot;为什么自定义 title 命令没有效果&quot;">​</a></h2><p>检查这几点：</p><ul><li>命令不要以 <code>/</code> 开头。</li><li>JSON 文本中的双引号需要保持 YAML 字符串合法。</li><li>低版本服务端的 <code>title</code> 命令格式可能不同。</li><li>先在控制台手动执行展开后的命令，确认服务端本身支持。</li></ul><h2 id="修改配置后需要重启吗" tabindex="-1">修改配置后需要重启吗 <a class="header-anchor" href="#修改配置后需要重启吗" aria-label="Permalink to &quot;修改配置后需要重启吗&quot;">​</a></h2><p>大多数配置可以通过以下命令重载：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurtp reload</span></span></code></pre></div><p>重载会重新读取配置、<code>lang/</code> 语言文件、旧 <code>messages.yml</code> 覆盖、世界规则、Vault 状态，并刷新 PlaceholderAPI 注册。若你替换了 jar、安装了依赖或更新了服务端核心，建议重启服务器。</p><h2 id="placeholderapi-变量没有值" tabindex="-1">PlaceholderAPI 变量没有值 <a class="header-anchor" href="#placeholderapi-变量没有值" aria-label="Permalink to &quot;PlaceholderAPI 变量没有值&quot;">​</a></h2><p>依次确认 PlaceholderAPI 已启用、<code>integrations.placeholderapi.enabled</code> 为 <code>true</code>，并在安装或替换 PlaceholderAPI 后重启过服务器。执行 <code>/papi parse me %yurtp_status%</code> 测试玩家变量；全局变量可用 <code>%yurtp_version%</code>。修改开关后可执行 <code>/yurtp reload</code> 刷新注册。</p><p>位置类变量在玩家尚无传送快照时返回空字符串，这是正常行为；未知变量返回 <code>null</code>。</p><h2 id="folia-上需要额外配置吗" tabindex="-1">Folia 上需要额外配置吗 <a class="header-anchor" href="#folia-上需要额外配置吗" aria-label="Permalink to &quot;Folia 上需要额外配置吗&quot;">​</a></h2><p>不需要。插件声明 <code>folia-supported: true</code>，会在运行时检测 Folia 并使用 Global、Region 和 Entity Scheduler。若其他插件通过 Java API 的 future 回调或事件操作实体、区块，请仍按 Folia 规则调度到对应实体或区域，不能假设回调位于传统主线程。</p><h2 id="bstats-可以关闭吗" tabindex="-1">bStats 可以关闭吗 <a class="header-anchor" href="#bstats-可以关闭吗" aria-label="Permalink to &quot;bStats 可以关闭吗&quot;">​</a></h2><p>可以在服务器的 bStats 配置中关闭。关闭后不会影响随机传送、冷却、扣费或世界规则。</p>`,49)])])}const u=s(t,[["render",n]]);export{k as __pageData,u as default};
